# Deer Creek
dict(ceq_id="R0233",project_name="Deer Creek Station (Basin Electric, gas combined cycle, Brookings County SD)",metric="nameplate_capacity",unit="MW",value_low="",value_central="300",value_high="",new_or_existing="new_build",status_2026="operating",status_year="2012",status_source_url=DCPUC,source_url=DCD,source_quote="The proposed Project has been sized for 300 MW in order to meet the 250 MW intermediate power supply need and have a 50 MW reserve to meet peak intermediate needs.",confidence="high",notes="Natural gas combined cycle (one GE 7FA CT + steam turbine with duct firing per trade press). Intermediate-load unit (EIS: 20-80% CF class) but GHG table assumes 8,760 hr/yr. Commercial operation Aug 2012 per Basin Electric 10-yr plan filed with SD PUC (search snippet; medium). Value from DEIS (WAPA); FEIS not opened (rd.usda.gov link dead). 2026 operating status not independently verified."),
dict(ceq_id="R0233b",project_name="Deer Creek Station - EIS annual CO2e",metric="co2_annual_eis",unit="MtCO2e_per_yr",value_low="",value_central="0.93",value_high="",new_or_existing="new_build",status_2026="operating",status_year="2012",status_source_url=DCPUC,source_url=DCD,source_quote="The operation of the 300-MW Deer Creek Station would release an estimated 1.02 million tons of CO2 equivalent (0.93 million metric tons) into the atmosphere each year (table 4-2).",confidence="high",notes="Metric tonnes stated explicitly. Table 4-2 assumes CT (1,434 MMBtu/hr) and duct burner (610.4 MMBtu/hr) at 8,760 hr/yr, i.e. a potential-to-emit upper bound (100% CF); actual intermediate-duty emissions lower. capture_rate 0."),
# Groton
dict(ceq_id="R0402",project_name="Groton Generation Station operating-limit removal (Basin Electric, Brown County SD)",metric="nameplate_capacity",unit="MW",value_low="",value_central="200",value_high="",new_or_existing="continuation",status_2026="operating",status_year="2011",status_source_url=GROT,source_url=GROT,source_quote="Groton Generation Station has two generating units. Each unit is powered by a General Electric (GE) LMS100 simple cycle gas turbine rated at 100 MW at design conditions. Unit 1... July 1, 2006, and Unit 2... July 1, 2008.",confidence="high",notes="Existing gas peaker; no construction. Action = WAPA LGIA change removing the 50-MW annual-average limit (ROD Dec 2011). CHANGE: output cap 438,000 MWh/yr (25% CF, = 2,190 full-load station-hours at 200 MW) -> 743,760 MWh/yr (42.5% CF, = 3,718.8 station full-load hours/yr, bound by Title V 238 tpy NOx and CO limits); +305,760 MWh/yr. Full output (1,752,000 MWh) would need PSD modification. Status 2026 assumed operating (not independently verified)."),
dict(ceq_id="R0402b",project_name="Groton Generation Station - EIS annual CO2e (with vs without limit)",metric="co2_annual_eis",unit="MtCO2e_per_yr",value_low="0.186",value_central="0.318",value_high="",new_or_existing="continuation",status_2026="operating",status_year="2011",status_source_url=GROT,source_url=GROT,source_quote="Station GHG Emissions (CO2e) 186,322 mtons CO2e/yr [with 50-MW limit] 318,098 mtons CO2e/yr [without limit] 749,299 mtons CO2e/yr [full output]",confidence="high",notes="Metric tons. low = No Action (50-MW limit), central = proposed action. INCREMENTAL emissions from the federal action = 131,776 tCO2e/yr (derived). ES text says 187,322 for no-action vs Table 2.1 186,322 (internal EIS inconsistency, 1,000 t)."),
# Kemper
dict(ceq_id="R0526",project_name="Kemper County IGCC (Mississippi Power / Southern Co.)",metric="nameplate_capacity",unit="MW",value_low="",value_central="582",value_high="",new_or_existing="new_build",status_2026="cancelled",status_year="2017",status_source_url=KST,source_url=KFEIS,source_quote="the Kemper County IGCC Project would generate a nominal 582 MW (net) of electricity when duct firing natural gas (for supplemental energy input) in the HRSG",confidence="high",notes="Lignite IGCC (two TRIG gasifiers, 2 CTs + ST) with adjacent Liberty Fuels lignite mine (~4.3 Mt/yr for up to 40 yr, ROD). capture_rate 67% (ROD: 'DOE has decided to fund includes a capture rate of 67 percent'; EIS analysed 25/50/67/>67%). CO2 to EOR. Capacity factor analysed 85%. STATUS: lignite gasification suspended June 2017; gasifier structures imploded Oct 2021; the combined-cycle units continue to operate on NATURAL GAS as Plant Ratcliffe (MS PSC commissioner note, medium). Coal/CCS component = cancelled; gas CC = operating."),
dict(ceq_id="R0526b",project_name="Kemper County IGCC - EIS annual CO2 (after 67% capture)",metric="co2_annual_eis",unit="million_tons_CO2_per_yr_as_stated_in_EIS",value_low="1.8",value_central="1.8",value_high="2.6",new_or_existing="new_build",status_2026="cancelled",status_year="2017",status_source_url=KST,source_url=KROD,source_quote="The project, operating at an 85-percent capacity factor (i.e., at full capacity), will emit approximately 1.8 million tpy of CO2 while burning lignite coal and firing natural gas in the duct burners.",confidence="high",notes="ROD also: 'would also emit an estimated 1.8 to 2.6 million tpy of CO2 annually' (range spans capture-rate alternatives); +~91,000 tpy other GHG; +~130,000 t life-cycle support/mining (total ~2.0 Mt). 'tpy' = short tons by US convention (1.8 Mst = 1.63 Mt metric). Lignite feed 13,800 tons/day. As-operated since 2017 the plant is an NGCC with no capture, so actual emissions differ from the EIS case."),
# FutureGen
dict(ceq_id="R0342",project_name="FutureGen 2.0 (Meredosia IL Unit 4 oxy-combustion repowering + CO2 storage)",metric="nameplate_capacity",unit="MW",value_low="",value_central="168",value_high="",new_or_existing="expansion",status_2026="cancelled",status_year="2015",status_source_url=FGST,source_url=FGROD,source_quote="The repowered unit would generate 168 MWe of power (gross) and CO2 suitable for transport by pipeline.",confidence="high",notes="Repowering of existing Ameren Meredosia Unit 4 (retrofit; new_or_existing could also be read as 'new_build' of the oxy-combustion boiler). Fuel: 60% Illinois No. 6 bituminous / 40% PRB blend. capture_rate >=90% (ROD). DOE suspended funding Feb 2015 (Recovery Act deadline Sept 2015); Alliance ceased development Jan 2016 (trade press via search snippets; status confidence medium-low). Never built."),
dict(ceq_id="R0342b",project_name="FutureGen 2.0 - CO2 captured and stored",metric="co2_captured_annual_eis",unit="MtCO2_per_yr",value_low="",value_central="1.1",value_high="",new_or_existing="expansion",status_2026="cancelled",status_year="2015",status_source_url=FGST,source_url=FGROD,source_quote="capture at least 90 percent (approximately 1.2 million tons [1.1 million metric tons] annually) of CO2 ... up to a total of 24 million tons (22 million metric tons) over approximately 20 years",confidence="high",notes="Captured, not emitted. Residual stack emissions not extracted (~0.12 Mt/yr if exactly 90%, derived). Net emissions effect of the project is a reduction vs. a conventional unit."),
# TCEP
dict(ceq_id="R1016",project_name="Texas Clean Energy Project (Summit, IGCC polygen, Odessa/Penwell TX)",metric="nameplate_capacity",unit="MW",value_low="",value_central="400",value_high="",new_or_existing="new_build",status_2026="cancelled",status_year="2016",status_source_url=TST,source_url=TROD,source_quote="Summit's TCEP will generate up to 400 megawatts (MW), of which 130 to 213 MW (approximately 1.0 to 1.7 billion net kilowatt-hours of electricity per year) will be available to the electricity grid.",confidence="high",notes="400 MW GROSS; only 130-213 MW NET to grid (row R1016c; rest used internally incl. urea plant). PRB sub-bituminous coal IGCC with urea production; capture_rate ~90%. DOE notified intent to discontinue cooperative agreement June 2016; terminated thereafter (DOE OIG 2018 audit). Never built. status_year 2016 medium."),
dict(ceq_id="R1016b",project_name="Texas Clean Energy Project - EIS annual CO2 emitted",metric="co2_annual_eis",unit="million_tons_CO2_per_yr_as_stated_in_EIS",value_low="",value_central="0.3",value_high="",new_or_existing="new_build",status_2026="cancelled",status_year="2016",status_source_url=TST,source_url=TROD,source_quote="Annual emissions of CO2 from the TCEP operations will range up to 300,000 tons per year",confidence="high",notes="Emitted after capture. Captured: 'up to 3 million tons (2.7 million metric tonnes) of CO2 annually', 2.5-3.0 Mst sold for EOR in Permian Basin. Emissions from urea use and EOR not counted."),
dict(ceq_id="R1016c",project_name="Texas Clean Energy Project - net power to grid",metric="net_capacity_to_grid",unit="MW",value_low="130",value_central="213",value_high="",new_or_existing="new_build",status_2026="cancelled",status_year="2016",status_source_url=TST,source_url=TROD,source_quote="of which 130 to 213 MW (approximately 1.0 to 1.7 billion net kilowatt-hours of electricity per year) will be available to the electricity grid",confidence="high",notes="Range stated in ROD; central set to upper bound of the stated range (no single value given). 1.0-1.7 TWh/yr net."),
# East Lynn Lake
dict(ceq_id="R0272",project_name="East Lynn Lake Coal Lease (WVES-50556 Argus + WVES-50560 Rockspring, Wayne County WV)",metric="coal_reserves_leased",unit="million_short_tons",value_low="",value_central="26",value_high="",new_or_existing="continuation",status_2026="unknown",status_year="2014",status_source_url=ELL,source_url=ELL,source_quote="The ELL Argus tract reserve contains 15 million tons of recoverable high-volatile A and B bituminous coal... 12,500-13,200 Btu/lb... The ELL Rockspring tract contains approximately 11 million tons of recoverable",confidence="high",notes="Underground mining from adjacent private mines (Argus, Rockspring); ~13,090 acres beneath USACE East Lynn Lake project lands. ROD 15 Mar 2013. Competitive sale scheduled 4 Dec 2014; OUTCOME NOT FOUND (no follow-up FR notice found; web search budget exhausted). Production rate NOT FOUND in EIS; 2008 Herald-Dispatch said 26.2 Mt over 10-15 years (~1.7-2.6 Mt/yr, derived; medium). Heat content 12,500-13,200 Btu/lb."),
# Greens Hollow
dict(ceq_id="N0043",project_name="Greens Hollow Coal Lease Tract (UTU-84102, SUFCO mine, Sanpete/Sevier UT)",metric="coal_reserves_leased",unit="million_short_tons",value_low="",value_central="55.7",value_high="",new_or_existing="continuation",status_2026="unknown",status_year="2017",status_source_url=GH16,source_url=GH16,source_quote="The coal beds contain approximately 73.4 million in-place tons of coal. However... the tract being offered for sale is projected to contain approximately 55.7 million tons of technically recoverable high-volatile C bituminous coal.",confidence="high",notes="6,175 acres, underground longwall via existing SUFCO mine (applicant Ark Land/Arch, later Canyon Fuel). NOI: extend SUFCO mine life by ~10 years (mine_life_extension_years=10) and 'maintain production'; implied ~5.6 Mt/yr (derived). Heat content 11,538-11,565 Btu/lb. FEIS Dec 2011 had no ROD; Supplemental EIS 2012-2015; sale noticed for 22 Sep 2016, postponed (litigation), reset to 4 Jan 2017. Sale OUTCOME NOT FOUND in sources opened (web search budget exhausted); my unverified recollection is that Canyon Fuel won and the lease was issued - VERIFY. In-place tons 73.4 Mt (not an alternative)."),
# West Elk
dict(ceq_id="R0304",project_name="West Elk Mine lease modifications COC-1362 & COC-67232 (Arch/Mountain Coal, Gunnison County CO) - 2012 FEIS",metric="coal_reserves_leased",unit="million_short_tons",value_low="",value_central="10",value_high="",new_or_existing="continuation",status_2026="operating",status_year="2017",status_source_url=WETAB,source_url=WE19,source_quote="Under Alternative 3, the E seam would be mined containing approximately 10 million tons of recoverable coal... producing approximately 4.5 million tons per year and continuing mining operations by approximately 3 years.",confidence="medium",notes="Tonnage from OSMRE 2019 mining-plan ROD describing the 2017 SFEIS Alt 3 (same 1,720-acre modifications); 2012 BLM ROD (Dec 2012) gave no tonnage but 'extend the existing operations approximately 19 months [federal] ... an additional 16-17 months of mining coal on adjacent private lands'. coal_production_rate ~4.5 Mt/yr; mine_life_extension ~3 yr (2017) or ~1.6 yr federal + ~1.4 yr private (2012). 2012 approvals vacated by D. Colo. 2014 (High Country Conservation Advocates v. USFS; social cost of carbon/GHG analysis) -> USFS SFEIS 2017 (not in this list) -> BLM ROD 15 Dec 2017, modifications effective 1 Dec 2017 (BLM table: COC-67232 920 acres, 559,000 tons offered, $167,700 = $0.30/ton). West Elk mine operating. Bituminous; Btu NOT FOUND. Substitution/GHG numbers from SFEIS NOT FOUND."),
dict(ceq_id="R0305",project_name="Federal Coal Lease Modifications COC-1362 and COC-67232 (BLM ROD, duplicate of R0304)",metric="coal_reserves_leased",unit="million_short_tons",value_low="",value_central="",value_high="",new_or_existing="continuation",status_2026="operating",status_year="2017",status_source_url=WETAB,source_url=WE12,source_quote="The BLM approves Alternative 3, to modify Mountain Coal Company's existing Federal coal lease COC-1362 by adding 921 acres and the Ark Land Companies existing Federal coal lease COC-67232 by adding 800 acres at the West Elk Mine.",confidence="medium",notes="DUPLICATE of R0304: values intentionally blank to avoid double counting; use R0304 (~10 Mt). Same project; R0304 = USFS consent ROD Aug 2012, R0305 = BLM ROD 28 Dec 2012). Do NOT double count. Note the 2012 BLM ROD assigns 921 ac to COC-1362 and 800 ac to COC-67232, opposite of the 2012 NOI and the 2018 BLM table (COC-67232 = 920 ac). The 'redo' is the 2017 USFS SFEIS (FR NOA 8 Sep 2017), not in the CEQ 2010-mid-2018 list as a separate row here."),
# Rusk
dict(ceq_id="R0892",project_name="Rusk Permit Area - South Hallsville No. 1 Lignite Mine expansion (Sabine Mining Co., for AEP Pirkey plant)",metric="coal_reserves_leased",unit="million_short_tons",value_low="",value_central="130",value_high="",new_or_existing="expansion",status_2026="unknown",status_year="",status_source_url=RUSK,source_url=RUSK,source_quote="The approximately 20,377-acre mine site would recover approximately 130 million tons of lignite during the 30-year life of the mine, for sole use at the existing H.W. Pirkey Power Plant",confidence="high",notes="USACE Section 404 permit (not a federal lease; private lignite). From the 2009 NOI; FEIS (May 2011) not opened. Implied ~4.3 Mt/yr over 30 yr (derived coal_production_rate); mine_life_extension 30 yr. Texas lignite (Btu NOT FOUND). STATUS: from memory only (unverified), AEP/SWEPCO retired Pirkey ~2023, which would end mining; verify before use."),
